'use strict';
const M=DemoModel,KEY='ltm-fictional-demo-v1',LANG='ltm-demo-language';
let mobileMenuOpen=false;
function setMenu(open,returnFocus=false){mobileMenuOpen=!!open;document.body.classList.toggle('menuOpen',mobileMenuOpen);const button=el('menu');button.setAttribute('aria-expanded',String(mobileMenuOpen));button.setAttribute('aria-label',mobileMenuOpen?t('Luk menu','Close menu'):t('Åbn menu','Open menu'));if(returnFocus)button.focus();}
let demoRole='admin',lang='en',data,screen='home',search='',filter='all',area='',color='status',selected='',reportMode='service',historyQuery='',reportYear,calendarYear,maps=[],toastTimer,dirty=false,memoryOnly=false;
try{lang=localStorage.getItem(LANG)==='da'?'da':'en';const raw=localStorage.getItem(KEY);if(raw){const s=JSON.parse(raw);if(s.schema===1&&s.fictional===true&&['cards','areas','publishers','loans','completions','notes','visits'].every(k=>Array.isArray(s[k])))data=s;}}catch{memoryOnly=true;}
if(!data)data=M.seed();
data.today=M.day(new Date());
M.linkLegacyCompletions(data);
function resetReport(){
 reportMode='service';historyQuery='';reportYear=M.year(data.today);calendarYear=Number(data.today.slice(0,4));
}
resetReport();
const el=id=>document.getElementById(id),t=(da,en)=>lang==='en'?en:da,e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=s=>s?new Date(s+'T12:00:00').toLocaleDateString(lang==='en'?'en-GB':'da-DK'):'—';
// Shared labels/colours keep the map and its legend in agreement.
const mapColours={assigned:'#4e95cc',folder:'#49a076',box:'#a48b6b',recent:'#499c77',middle:'#ba9a5a',older:'#b67562'};
function mapLegend(){const items=color==='age'?[['recent',t('Under 90 dage','Under 90 days')],['middle',t('90–179 dage','90–179 days')],['older',t('180+ dage eller ukendt','180+ days or unknown')]]:[['assigned',t('Udleveret','Assigned')],['folder',t('I mappen','In the carry folder')],['box',t('I kassen','In the storage box')]];return items.map(([key,text])=>`<span><i class="dot" style="background:${mapColours[key]}"></i>${text}</span>`).join('');}
function errorMessage(error){const message=String(error?.message||error);if(lang==='en')return message;return ({
 'Choose a card and publisher.':'Vælg et kort og en forkynder.',
 'This card is already assigned.':'Kortet er allerede udleveret.',
 'Choose a valid assignment date.':'Vælg en gyldig udleveringsdato, senest i dag.',
 'This card is not assigned.':'Kortet er ikke udleveret.',
 'Choose a return date after assignment and no later than today.':'Vælg en indleveringsdato fra udleveringsdatoen til i dag.',
 'The note is too long.':'Noten er for lang.',
 'Only available cards can be moved.':'Kun ledige kort kan flyttes.',
 'Check the number and name.':'Kontrollér kortnummer og navn.',
 'The card number already exists.':'Kortnummeret findes allerede.',
 'Choose an area and type.':'Vælg et område og en type.',
 'Choose where the physical card is kept.':'Vælg, hvor det fysiske kort ligger.',
 'This assignment is no longer available.':'Udleveringen findes ikke længere.',
 'The date overlaps another assignment for this card.':'Datoen overlapper en anden udlevering af samme kort.'
 })[message]||message;}
const card=id=>data.cards.find(c=>c.id===id),areaName=id=>data.areas.find(a=>a.id===id)?.name||'—',person=id=>data.publishers.find(p=>p.id===id)?.name||'—',byNumber=(a,b)=>a.number.localeCompare(b.number,undefined,{numeric:true});
const label=s=>({assigned:t('Udleverede distriktskort','Assigned territories'),folder:t('Kort i mappen','Cards in the carry folder'),box:t('Kort i kassen','Cards in the storage box')}[s]||s),badge=c=>`<span class="badge ${M.position(data,c)}">${label(M.position(data,c))}</span>`;
function toast(s){el('toast').textContent=s;el('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el('toast').hidden=true,4000);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(data));memoryOnly=false;}catch{memoryOnly=true;toast(t('Kun gemt i denne åbne fane · browserlagring er ikke tilgængelig.','Kept in this tab only · browser storage is unavailable.'));}return !memoryOnly;}
function dispose(){maps.forEach(m=>m.remove());maps=[];}
function close(force=false){if(dirty&&!force&&!confirm(t('Luk formularen uden at gemme?','Close this form without saving?')))return false;dirty=false;el('dialog').close();document.body.classList.remove('printingCard');render();return true;}
function dialog(html){if(el('dialog').open&&!close())return;dirty=false;el('dialog').innerHTML='<button class="dialogClose" data-do="close" aria-label="'+t('Luk','Close')+'">×</button><p class="eyebrow">DEMO · '+t('OPDIGTEDE DATA','FICTIONAL DATA')+'</p>'+html+'<p class="dialogError" id="error" role="alert"></p>';el('dialog').showModal();el('dialog').scrollTop=0;}
function title(name,sub,action=''){return `<div class="top pageTitle"><div><h1>${name}</h1><p>${sub}</p></div>${action}</div>`;}
function yearLabel(y){return `${y-1}/${y}`;}
function yearSelect(mode){
 const calendar=mode==='calendar',readYear=calendar?date=>Number(date.slice(0,4)):M.year;
 const chosen=calendar?calendarYear:reportYear,id=calendar?'calendarYear':'reportYear';
 const years=[...new Set([readYear(data.today),chosen,...data.completions.map(c=>readYear(c.date))])].sort((a,b)=>b-a);
 return `<label class="demoYear">${calendar?t('Kalenderår','Calendar year'):t('Tjenesteår','Service year')}
  <select id="${id}">${years.map(y=>`<option value="${y}" ${chosen===y?'selected':''}>${calendar?y:yearLabel(y)}</option>`).join('')}</select></label>`;
}
function visible(){const q=search.toLocaleLowerCase();return data.cards.filter(c=>(filter==='all'||M.position(data,c)===filter)&&(!area||c.area_id===area)&&(!q||[c.number,c.name,areaName(c.area_id),...c.addresses.map(a=>a.road+' '+a.number)].join(' ').toLocaleLowerCase().includes(q))).sort(byNumber);}
function filters(withColor=false){return `<div class="toolbar noPrint"><input id="search" type="search" placeholder="${t('Søg nummer, navn eller vej…','Search number, name or road…')}" value="${e(search)}" aria-label="${t('Søg distrikter','Search territories')}"><select id="filter" aria-label="${t('Placering','Location')}"><option value="all">${t('Alle distriktskort','All territory cards')}</option>${['assigned','folder','box'].map(s=>`<option value="${s}" ${filter===s?'selected':''}>${label(s)}</option>`).join('')}</select><select id="area" aria-label="${t('Område','Area')}"><option value="">${t('Alle områder','All areas')}</option>${data.areas.map(a=>`<option value="${a.id}" ${a.id===area?'selected':''}>${e(a.name)}</option>`).join('')}</select>${withColor?`<select id="color" aria-label="${t('Farver','Colours')}"><option value="status" ${color==='status'?'selected':''}>${t('Farve efter placering','Colour by location')}</option><option value="age" ${color==='age'?'selected':''}>${t('Farve efter gennemgang','Colour by completion')}</option></select>`:''}</div>`;}
function table(cards,desk=false){return `<div class="tablewrap tableWrap"><table><thead><tr><th>${t('Kort','Card')}</th><th>${t('Område','Area')}</th><th>${t('Senest gennemgået','Last completed')}</th><th>${t('Status','Status')}</th><th></th></tr></thead><tbody>${cards.map(c=>`<tr class="cardRow" tabindex="0" data-card="${e(c.id)}" aria-label="${t('Åbn kort','Open card')} ${e(c.number)}"><td><b class="number">${e(c.number)}</b><small>${e(c.name||t('Midlertidigt kort','Temporary card'))}</small></td><td>${e(areaName(c.area_id))}<small>${c.kind==='Land'?t('Land','Rural'):c.kind==='By'?t('By','Urban'):t('Ukendt','Unknown')}</small></td><td>${fmt(c.last_completed)}<small>${M.count(c)} ${t('besøg','visits')}</small></td><td>${badge(c)}</td><td><div class="toolbar" style="margin:0">${desk?`<button data-do="${M.active(data,c.id)?'return':'assign'}" data-id="${e(c.id)}" class="${M.active(data,c.id)?'':'primary'}">${M.active(data,c.id)?t('Indlever','Return'):t('Udlever','Assign')}</button>`:''}${demoRole==='admin'?`<button data-do="map-card" data-id="${e(c.id)}">${t('Se på kort','Show on map')}</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>${cards.length?'':`<p class="empty">${t('Ingen kort matcher filtrene.','No cards match these filters.')}</p>`}`;}
function chart(period){
 const date=new Date(period.start+'T12:00:00'),months=[];
 date.setDate(1);
 for(;M.day(date)<period.end;date.setMonth(date.getMonth()+1)){
  const key=M.day(date).slice(0,7);
  const label=date.toLocaleDateString(lang==='en'?'en-GB':'da-DK',{month:'short',year:'2-digit'});
  const n=data.completions.filter(x=>x.date.startsWith(key)&&M.inPeriod(x.date,period)).length;
  months.push({key,label,n});
 }
 const max=Math.max(1,...months.map(m=>m.n));
 const co=data.visits.map(v=>v.date).filter(date=>M.inPeriod(date,period)).sort().at(-1);
 return `<div class="chart">${months.map(m=>`<div class="barItem" title="${e(m.key)} · ${m.n}"><b>${m.n}</b><span class="bar" style="height:${Math.max(2,m.n/max*110)}px"></span><small>${e(m.label)}</small>
 ${co?.startsWith(m.key)?'<span class="coLine" aria-hidden="true"></span>':''}</div>`).join('')}</div>
 ${co?`<p class="hint">↑ ${t('Sidste KTM-besøg','Last CO visit')} · ${fmt(co)}</p>`:''}`;
}
function followupItems(){const rows=[];for(const c of data.cards){if(c.temporary)rows.push({card:c,text:t('Midlertidigt kort · vejliste mangler','Temporary card · address list missing')});if(!c.area_id)rows.push({card:c,text:t('Mangler område','Missing area')});const l=M.active(data,c.id);if(l&&(Date.parse(data.today)-Date.parse(l.assigned))/86400000>123)rows.push({card:c,text:t('Langvarig udlevering · følg op','Long-running assignment · follow up')});}return rows;}
function followups(){const rows=followupItems();return title(t('Opfølgninger','Follow-ups'),t('Opdigtede eksempler på kortkontrol og udleveringer.','Fictional examples of card checks and assignments.'))+`<section class="panel"><p>${t('Til opfølgning:','Follow-up items:')} ${rows.length}</p>${rows.map(r=>`<article class="line followupRow"><div><strong>${t('Kort','Card')} ${e(r.card.number)}</strong><p>${e(r.text)}</p></div><button data-do="open" data-id="${e(r.card.id)}">${t('Åbn kort','Open card')}</button></article>`).join('')||`<p>${t('Ingen punkter i dette eksempel.','No items in this example.')}</p>`}<p class="hint">${t('Den installerede app viser også hver ændret printside og adresseændringer. Import og ægte printgodkendelser er ikke en del af demoen.','The installed app also lists each changed print side and address change. Import and real print approvals are not part of the demo.')}</p></section>`;}
function addresses(){return title(t('Kort og adresser','Cards and addresses'),t('Kun opdigtede adresser · ingen privat import.','Fictional addresses only · no private import.'))+`<section class="panel"><div class="tablewrap"><table><thead><tr><th>${t('Kort','Card')}</th><th>${t('Adresse','Address')}</th><th>${t('Besøg','Visits')}</th></tr></thead><tbody>${data.cards.flatMap(c=>c.addresses.map(a=>`<tr><td><button class="link" data-do="open" data-id="${e(c.id)}">${e(c.number)}</button></td><td>${e(a.road)} ${e(a.number)}</td><td>${Number(a.count||1)}</td></tr>`)).slice(0,100).join('')}</tbody></table></div></section>`;}
function home(){const s=M.stats(data),total=data.cards.length,out=s.assigned,home=s.folder+s.box,pct=total?Math.round(s.unique/total*100):0,pending=data.notes.filter(n=>!n.resolved&&n.task),items=followupItems(),ring=(part,value,label,hint)=>`<div class="dashboardRing" style="--portion:${Math.max(0,Math.min(100,part))}%"><div><strong>${value}</strong><span>${label}</span></div></div><p class="hint">${hint}</p>`;
return title(t('Forside','Home'),t('Status og udvikling i dette tjenesteår','Status and progress in this service year'))+`<section class="dashboardHero"><div><span class="eyebrow">${t('DIT LOKALE OVERBLIK','YOUR LOCAL OVERVIEW')}</span><h2>${t('Tjenesteår','Service year')} ${yearLabel(M.year(data.today))}</h2><p>${t('Kort, gennemgange og opfølgning — samlet ét sted.','Cards, completions and follow-up — in one place.')}</p></div><div class="heroActions"><button class="primary" data-go="desk">${t('Gå til daglig brug →','Open the territory desk →')}</button><span class="privacyBadge">${t('Demo · kun opdigtede data','Demo · fictional data only')}</span></div></section><div class="dashboardShortcuts">${[['folder',s.folder],['box',s.box]].map(([key,n])=>`<button data-go="territories" data-preset="${key}"><span>${label(key)}</span><strong>${n}</strong></button>`).join('')}<button data-go="tasks"><span>${t('Åbne opgaver','Open tasks')}</span><strong>${pending.length}</strong></button></div><div class="dashboardGrid"><section class="panel"><h3>${t('Kortenes placering','Card locations')}</h3>${ring(total?out/total*100:0,out,t('udleveret','assigned'),`${home} ${t('hjemme','at home')} · ${s.folder} ${t('i mappen','in the folder')} · ${total} ${t('kort i alt','cards in total')}`)}</section><section class="panel"><h3>${t('Dækning i tjenesteåret','Coverage in the service year')}</h3>${ring(pct,pct+'%',t('dækning','coverage'),`${s.unique} ${t('af','of')} ${total} ${t('forskellige kort gennemgået','different cards completed')}`)}</section></div><div class="dashboardMetrics"><section class="panel"><small>${t('Gennemgange i tjenesteåret','Completions in the service year')}</small><strong>${s.events}</strong><span>${t('Alle gennemgange tæller','All completions count')}</span></section><section class="panel"><small>${t('Anslåede besøg ved gennemgange','Estimated visits in completions')}</small><strong>${s.visits}</strong><span>${t('Ikke en registrering af faktiske husbesøg','Not a record of actual house visits')}</span></section><section class="panel"><small>${t('Gennemsnit mellem gennemgange','Average between completions')}</small><strong class="metricText">${s.average??'—'}</strong><span>${t('dage · kendte intervaller','days · known intervals')}</span></section><button class="panel taskMetric" data-go="tasks"><small>${t('Åbne opgaver','Open tasks')}</small><strong>${pending.length}</strong><span>${t('Se opgaver →','View tasks →')}</span></button></div><div class="dashboardLower"><section class="panel dashboardTrend"><h3>${t('Gennemgange pr. måned','Monthly completions')}</h3>${chart(M.period(data.today))}</section><section class="panel dashboardAttention"><span class="eyebrow">${t('NÆSTE SKRIDT','NEXT STEPS')}</span><h3>${t('Opfølgninger','Follow-ups')}</h3><p>${t('Til opfølgning:','Follow-up items:')} ${items.length}</p>${items.slice(0,3).map(r=>`<button class="attentionCard" data-do="open" data-id="${e(r.card.id)}"><span>${t('Kort','Card')} ${e(r.card.number)}<small>${e(r.text)}</small></span><span aria-hidden="true">→</span></button>`).join('')}<button class="attentionLink" data-go="followups">${t('Åbn opfølgninger →','Open follow-ups →')}</button></section></div>`;}
function desk(){return title(t('Daglig brug','Territory desk'),t('Find kortet, udlever det eller registrer en aflevering.','Find a card, assign it or record a return.'))+`<section class="panel">${filters()}${table(visible(),true)}</section>`;}
function territories(){return title(t('Distriktskort','Territory cards'),t('Søg i kortene, og klik på hele linjen for at åbne.','Search the cards and click anywhere on a row to open.'),`<button class="primary" data-do="new-card">＋ ${t('Tilføj midlertidigt kort','Add temporary card')}</button>`)+`<section class="panel">${filters()}${table(visible())}</section>`;}
function overview(){return title(t('Kortoversigt','Territory map'),t('Se placering og gennemgang med enkle filtre.','Explore location and completion using simple filters.'))+`<section class="panel">${filters(true)}<div id="overviewMap" class="map"></div><div class="mapLegend">${mapLegend()}</div><p class="mapCaption">${t('Alle grænser og besøg her er opdigtede eksempler. Kortbaggrund: OpenStreetMap.','All boundaries and visit locations here are invented examples. Map background: OpenStreetMap.')}</p><p>${visible().length} ${t('kort matcher filtrene. Klik på en flade for at åbne.','cards match these filters. Click a territory to open it.')}</p></section>`;}
function publishers(){return title(t('Forkyndere','Publishers'),t('Se hvem der har hvilke distriktskort.','See who has which territory cards.'),`<button data-do="new-publisher">＋ ${t('Tilføj demoforkynder','Add demo publisher')}</button>`)+`<section class="panel">${data.publishers.map(p=>{const loans=data.loans.filter(l=>l.publisher_id===p.id&&!l.returned);return `<div class="listLine"><div><b>${e(p.name)}</b><p class="hint">${loans.length} ${t('udleverede distriktskort','assigned territory cards')}</p></div><div class="toolbar" style="margin:0">${loans.map(l=>`<button data-do="open" data-id="${e(l.card_id)}">${e(card(l.card_id)?.number)}</button>`).join('')||'—'}</div></div>`;}).join('')}</section>`;}
function tasks(){return title(t('Opgaver og noter','Tasks and notes'),t('Et samlet sted til opfølgning.','One place for follow-up.'),`<button data-do="new-note">＋ ${t('Tilføj note','Add note')}</button>`)+`<section class="panel">${data.notes.slice().sort((a,b)=>Number(a.resolved)-Number(b.resolved)||b.date.localeCompare(a.date)).map(n=>`<div class="listLine ${n.resolved?'taskDone':''}"><div><p class="detailNotes">${e(n.text)}</p><small class="hint">${fmt(n.date)}${n.card_id?' · '+t('Kort','Card')+' '+e(card(n.card_id)?.number):''} · ${n.task?t('Opgave','Task'):t('Note','Note')}</small></div><button data-do="resolve" data-id="${e(n.id)}">${n.resolved?t('Genåbn','Reopen'):t('Afslut','Complete')}</button></div>`).join('')||`<p class="empty">${t('Ingen noter endnu.','No notes yet.')}</p>`}</section>`;}
const reportTabs=[
 ['calendar','Kalenderår','Calendar year'],['service','Tjenesteår','Service year'],
 ['rolling','Seneste 12 måneder','Last 12 months'],['history','Korthistorik','Card history'],['visits','KTM-besøg','CO visits']
];
function reportPeriod(mode=reportMode){return M.period(data.today,mode,mode==='calendar'?calendarYear:reportYear);}
function reportDates(p){return `${fmt(p.start)} – ${fmt(M.offset(p.end,-1))}`;}
function reportHeading(mode){
 const [,da,en]=reportTabs.find(([key])=>key===mode);
 const year=mode==='calendar'?calendarYear:mode==='service'?yearLabel(reportYear):'';
 return [t(da,en),year].filter(Boolean).join(' ');
}
const reportLabels=()=>({
 events:t('Gennemgange','Completions'),total:t('Aktuelle distrikter','Current territories'),
 covered:t('Gennemgåede aktuelle distrikter','Current territories completed'),
 missing:t('Ikke registreret gennemgået i perioden','No completion recorded in the period'),
 missingAssigned:t('Heraf udleveret nu','Of these, currently assigned'),
 missingHome:t('Heraf hjemme nu','Of these, currently available')
});
function reportMetrics(stats){
 return `<div class="metrics">${Object.entries(reportLabels()).map(([key,label])=>
  `<div><small>${label}</small><strong>${stats[key]}</strong></div>`).join('')}</div>`;
}
const reportMark=()=>`<div class="eyebrow reportMark">DEMO · ${t('OPDIGTEDE DATA','FICTIONAL DATA')}</div>`;
function printableReportMap(cards,covered){
 const polygons=cards.filter(c=>c.polygon.length>=3).map(c=>({id:c.id,points:c.polygon.map(([lng,lat])=>
  [lng*Math.PI/180,Math.log(Math.tan(Math.PI/4+lat*Math.PI/360))])}));
 if(!polygons.length)return '';
 const points=polygons.flatMap(c=>c.points),xs=points.map(p=>p[0]),ys=points.map(p=>p[1]);
 const left=Math.min(...xs),right=Math.max(...xs),bottom=Math.min(...ys),top=Math.max(...ys);
 const scale=Math.min(660/(right-left),355/(top-bottom));
 if(!Number.isFinite(scale))return '';
 const width=(right-left)*scale,height=(top-bottom)*scale,x=(700-width)/2,y=(395-height)/2;
 return `<svg class="printOnly reportPrintMap" viewBox="0 0 700 395" role="img" aria-label="${t('Opdigtede distriktsgrænser','Fictional territory boundaries')}">
 <rect width="700" height="395" fill="#edf1ef"/>
 <rect x="${x-8}" y="${y-8}" width="${width+16}" height="${height+16}" fill="none" stroke="#b74337" stroke-width="2" stroke-dasharray="6 4"/>
 ${polygons.map(c=>`<polygon points="${c.points.map(([lng,lat])=>[(x+(lng-left)*scale).toFixed(2),(y+(top-lat)*scale).toFixed(2)].join(',')).join(' ')}"
  fill="${covered.has(c.id)?'#81bd9b':'#d6dfe4'}" stroke="${covered.has(c.id)?'#257648':'#657887'}" stroke-width="1.5"/>`).join('')}</svg>`;
}
function reportDetails(period,s){
 const labels=reportLabels(),rows=[['total','assigned','home'],['missing','missingAssigned','missingHome']];
 return `<section class="report">${reportMark()}<h2>${t('Aktuelle distrikter og udlevering','Current territories and assignments')}</h2>
 <p>${t('Status den','Status as of')} ${fmt(data.today)}</p><div class="tablewrap"><table>
 <thead><tr><th scope="col">${t('Distrikter','Territories')}</th><th scope="col">${t('I alt','Total')}</th>
 <th scope="col">${t('Udleveret nu','Currently assigned')}</th><th scope="col">${t('Hjemme nu','Currently available')}</th></tr></thead>
 <tbody>${rows.map(([label,...values])=>`<tr><th scope="row">${labels[label]}</th><td>${s[label]}</td>${values.map(k=>`<td>${s[k]}</td>`).join('')}</tr>`).join('')}</tbody>
 </table></div><p>${t('Periode','Period')} · ${reportDates(period)}</p></section>`;
}
function reports(){
 const tabs=`<div class="tabs noPrint" role="group" aria-label="${t('Rapportvisning','Report view')}">${reportTabs.map(([mode,da,en])=>
  `<button data-do="report-mode" data-mode="${mode}" aria-pressed="${mode===reportMode}" class="${mode===reportMode?'active':''}">${t(da,en)}</button>`).join('')}</div>`;
 const header=title(t('Rapporter og historik','Reports and history'),t('Perioder, korthistorik og KTM-besøg','Periods, card history and CO visits'),
  reportMode==='service'?yearSelect('service'):'');
 if(reportMode==='history')return header+tabs+history();
 if(reportMode==='visits')return header+tabs+visitList();
 const period=reportPeriod(),s=M.inventory(data,period);
 return header+tabs+`<div class="toolbar noPrint">
 ${reportMode==='calendar'?yearSelect('calendar'):''}
 <button class="primary" data-do="print-report">${t('Print demorapport / PDF','Print demo report / PDF')}</button></div>
 <section class="report reportSummary">${reportMark()}
 <h2>${reportHeading(reportMode)}</h2><small>${reportDates(period)} · ${t('Rapport udarbejdet den','Report prepared on')} ${fmt(data.today)}</small>
 ${reportMetrics(s)}<p class="hint">${t('Gentagne gennemgange tæller hver gang. Aktuelle distrikter tæller én gang. Udleveret og hjemme beskriver status nu.','Repeated completions count each time. Current territories count once. Assigned and available describe the current status.')}</p>
 <div class="reportchart"><h3>${t('Gennemgange pr. måned','Monthly completions')}</h3>${chart(period)}</div></section>
 <section class="report reportScreenMap">${reportMark()}<h2>${t('Gennemgåede distrikter','Completed territories')} · ${reportHeading(reportMode)}</h2><p>${reportDates(period)}</p>
 <div id="reportMap" class="map reportMap noPrint"></div>${printableReportMap(data.cards,s.coveredIds)}<p class="mapCaption">${t('Grøn: gennemgang registreret i perioden. Grå: ingen gennemgang registreret i perioden. Rød stiplet linje: samlet demogrænse.','Green: a completion was recorded in the period. Grey: no completion recorded in the period. Red dashed line: overall fictional boundary.')}</p></section>
 ${reportDetails(period,s)}<section class="panel noPrint"><h2>S-13</h2><p>${t('Original udfyldt S-13 og samlet rapport med alle perioder findes i den installerede app. Demoen udskriver den viste periode med opdigtede data.','The installed app provides the original filled-in S-13 and a combined report for all periods. The demo prints the displayed period with fictional data.')}</p></section>`;
}
function history(){
 const query=historyQuery.trim().toLocaleLowerCase();
 const cards=data.cards.filter(c=>[c.number,c.name,areaName(c.area_id),...c.addresses.map(a=>a.road+' '+a.number)].join(' ').toLocaleLowerCase().includes(query)).sort(byNumber);
 const rows=cards.map(c=>{
  const loans=data.loans.filter(l=>l.card_id===c.id).sort((a,b)=>b.assigned.localeCompare(a.assigned));
  const completions=data.completions.filter(x=>x.card_id===c.id).sort((a,b)=>b.date.localeCompare(a.date));
  const earlier=loans.length-3;
  const loanLine=l=>{
   const dates=completions.filter(x=>x.loan_id===l.id).map(x=>fmt(x.date));
   return `<div class="historyLoan"><span>${fmt(l.assigned)} → <b>${l.returned?fmt(l.returned):t('Stadig udleveret','Still assigned')}</b></span>
    <small>${e(person(l.publisher_id))} · ${dates.length?t('gennemgået','completed')+' '+dates.join(', '):t('ingen gennemgang registreret','no completion recorded')}</small>
    <div class="actions"><button data-do="correct-loan" data-id="${e(l.id)}">${t('Ret udlevering','Correct assignment')}</button><button data-do="delete-loan" data-id="${e(l.id)}">${t('Slet udlevering','Delete assignment')}</button></div></div>`;
  };
  return `<tr><td><b>${e(c.number)} ${e(c.name)}</b><small>${e(areaName(c.area_id))}</small><small>${t('Senest gennemgået','Last completed')} ${fmt(c.last_completed)}</small>
  <button data-do="open" data-id="${e(c.id)}">${t('Åbn kort','Open card')}</button></td>
  <td>${loans.slice(0,3).map(loanLine).join('')||t('Ingen udleveringer','No assignments')}
  ${earlier>0?`<details><summary>${earlier} ${t('tidligere udleveringer','earlier assignments')}</summary>${loans.slice(3).map(loanLine).join('')}</details>`:''}
  <details><summary>${t('Alle registrerede gennemgange','All recorded completions')}</summary>
  ${completions.map(x=>`<p>${fmt(x.date)} · ${x.loan_id?t('tilknyttet udlevering','linked to an assignment'):t('kendt gennemgang','known completion')}
    <button data-do="delete-completion" data-id="${e(x.id)}">${t('Slet gennemgang','Delete completion')}</button></p>`).join('')||t('Ingen gennemgange registreret.','No completions recorded.')}</details></td></tr>`;
 }).join('');
 return `<div class="toolbar"><input type="search" id="historySearch" value="${e(historyQuery)}" placeholder="${t('Søg kort, område eller vej','Search card, area or road')}" aria-label="${t('Søg i korthistorik','Search card history')}"></div>
 <section class="panel"><h2>${t('Udleveringer og gennemgange','Assignments and completions')}</h2>
 <p class="hint">${t('Ét kort pr. række. Udlevering, aflevering og gennemgang er forskellige registreringer.','One card per row. Assignment, return and completion are separate records.')}</p>
 ${rows?`<div class="tablewrap"><table class="historyTable"><thead><tr><th scope="col">${t('Kort / seneste gennemgang','Card / latest completion')}</th>
 <th scope="col">${t('Udlevering → aflevering · nyeste først','Assignment → return · newest first')}</th></tr></thead><tbody>${rows}</tbody></table></div>`:
 `<p class="empty">${t('Ingen kort matcher søgningen.','No cards match the search.')}</p>`}</section>`;
}
