function settings(){return title(t('Om demoen','About the demo'),t('Prøv arbejdsgangene, før du installerer.','Try the workflows before installing.'))+`<section class="panel aboutGrid"><div><h2>${t('Hvad kan jeg prøve?','What can I try?')}</h2><ul><li>${t('Find, udlever og indlever distriktskort.','Find, assign and return territory cards.')}</li><li>${t('Tilføj note/opgave ved aflevering.','Add a note/task when returning a card.')}</li><li>${t('Flyt ledige kort mellem mappe og kasse.','Move available cards between the carry folder and storage box.')}</li><li>${t('Se forkyndere, kortgrænser, besøg og gennemgange.','Explore publishers, boundaries, visits and completions.')}</li><li>${t('Opret et midlertidigt kort og tilføj en demoforkynder.','Create a temporary card and add a demo publisher.')}</li></ul></div><div><h2>${t('Kun opdigtede oplysninger','Fictional records only')}</h2><p>${t('Bornholm er inspiration til eksemplerne. Dette er ingen virkelig menigheds kort, adresser, grænser eller forkyndere. Skriv også kun opdigtede oplysninger i demoen.','Bornholm inspires these examples. These are not a real congregation’s cards, addresses, boundaries or publishers. Only enter fictional information in the demo.')}</p><p>${t('Dine demoændringer ligger kun i denne browsers lokale lagring. Andre besøgende ser dem ikke. Ingen rigtig app eller Google-konto forbindes.','Your demo changes stay in this browser’s local storage. Other visitors cannot see them. No real application or Google account is connected.')}</p></div><div><h3>${t('Når du installerer','When you install')}</h3><p>${t('Du får Python/SQLite-appen på Mac, Windows eller Home Assistant. Den har også KML, adressehentning, tegnede grænser, lokal IB-import, original S-13 og valgfri godkendt PNG-deling til Drive. Disse funktioner udføres ikke i denne browserdemo.','The Python/SQLite app runs on Mac, Windows or Home Assistant. It also includes KML, address downloads, boundary drawing, local DNC import, original S-13 and optional approved PNG sharing to Drive. Those features do not run in this browser demo.')}</p><p>${t('Med HA kan du forbinde telefonen til din egen router-VPN og åbne den private app-adresse udefra.','With HA, connect your phone to your own router VPN to open the private app address while away.')}</p><a href="https://github.com/Bib007/LTM-Local-Territory-Manager" target="_blank" rel="noopener">${t('Se projekt og installationsguide','View project and installation guide')} ↗</a></div><div><h3>${t('Start demoen forfra','Start the demo again')}</h3><p>${t('Nulstilling sletter kun denne browsers demoændringer og gendanner de opdigtede eksempler.','Reset removes only this browser’s demo changes and restores the fictional examples.')}</p><button class="danger" data-do="reset">${t('Nulstil demo','Reset demo')}</button><p class="hint">${t('Kortfliser hentes fra OpenStreetMap. Der bruges ingen adresse-/Google-API, og ingen private filer kan importeres.','Map tiles come from OpenStreetMap. No address/Google API is used, and private files cannot be imported.')}</p></div></section>`;}
function render(){if(demoRole==='assistant'&&!['desk','settings'].includes(screen))screen='desk';dispose();document.documentElement.lang=lang;setMenu(mobileMenuOpen);el('language').value=lang;const pages=[['home','⌂',t('Forside','Home')],['desk','⇄',t('Daglig brug','Territory desk')],['territories','▤',t('Distriktskort','Territory cards')],['map','◇',t('Kortoversigt','Territory map')],['publishers','♙',t('Forkyndere','Publishers')],['tasks','☑',t('Opgaver og noter','Tasks and notes')],['followups','◉',t('Opfølgninger','Follow-ups')],['reports','▥',t('Rapporter og historik','Reports and history')],['addresses','⌖',t('Kort og adresser','Cards and addresses')],['settings','⚙',t('Indstillinger','Settings')]];
 el('nav').innerHTML=`<label>${t('Prøv en rolle','Try a role')}<select id="demoRole"><option value="admin" ${demoRole==='admin'?'selected':''}>${t('Administrator','Administrator')}</option><option value="assistant" ${demoRole==='assistant'?'selected':''}>${t('Udleveringsassistent','Assignment assistant')}</option></select></label>`+pages.filter(([id])=>demoRole==='admin'||['desk','settings'].includes(id)).map(([id,icon,name])=>`${id==='territories'?'<div class="navcaption">'+t('OVERBLIK','OVERVIEW')+'</div>':id==='reports'?'<div class="navcaption">'+t('ADMINISTRATION','ADMINISTRATION')+'</div>':''}<button data-go="${id}" ${id===screen?'aria-current="page"':''}><span class="navIcon" aria-hidden="true">${icon}</span>${name}</button>`).join('');el('notice').textContent=t('DEMO · Kun opdigtede Bornholm-data. Ændringer gælder kun i din browser. Brug ikke virkelige oplysninger.','DEMO · Entirely fictional Bornholm data. Changes apply only in your browser. Do not enter real information.');el('asideNote').textContent=t('Et uofficielt værktøj. Den installerede app kører lokalt på dit eget system.','An unofficial tool. The installed app runs locally on your own system.');el('footer').textContent='Local Territory Manager – JW · '+t('Demo · kun opdigtede oplysninger','Demo · fictional records only')+(memoryOnly?' · '+t('Kun hukommelse i denne fane','Memory in this tab only'):'');
 if(typeof Theme!=='undefined')el('appearance').innerHTML=Theme.html(lang);el('content').innerHTML=({home,desk,territories,map:overview,publishers,tasks,followups,addresses,reports,settings}[screen]||home)();if(screen==='map')mountMap('overviewMap',visible());if(screen==='reports'&&!['history','visits'].includes(reportMode))mountMap('reportMap',data.cards,{report:true});
}
function mountMap(nodeId,cards,{report=false,detail=false}={}){if(typeof L==='undefined'){el(nodeId).textContent=t('Kortbiblioteket kunne ikke indlæses.','The map library could not be loaded.');return;}const node=el(nodeId);if(!node)return;const map=L.map(node,{preferCanvas:false,zoomAnimation:false,zoomControl:!report,dragging:!report,scrollWheelZoom:!report,doubleClickZoom:!report,touchZoom:!report,boxZoom:!report,keyboard:!report}).setView([55.14,14.93],10);maps.push(map);map.attributionControl.setPrefix(false);const tile=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a>'}).addTo(map);let failed=false;tile.on('tileerror',()=>{if(!failed){failed=true;node.setAttribute('aria-label',t('Kortbaggrund kan ikke hentes. De opdigtede grænser vises stadig.','Map background unavailable. Fictional boundaries remain visible.'));}});
 const done=report?M.inventory(data,reportPeriod()).coveredIds:null,all=[];
 for(const c of cards){if(c.polygon.length<3)continue;const pts=c.polygon.map(p=>[p[1],p[0]]);all.push(...pts);const age=c.last_completed?(Date.parse(data.today)-Date.parse(c.last_completed))/86400000:Infinity,col=report?(done.has(c.id)?'#2a995b':'#8b98a2'):color==='age'?mapColours[age<90?'recent':age<180?'middle':'older']:mapColours[M.position(data,c)];const shape=L.polygon(pts,{color:col,weight:2,fillOpacity:report?(done.has(c.id) ? .5 : .08):.3,interactive:!report}).addTo(map);if(!report){shape.bindTooltip(e(c.number)+' · '+e(c.name));shape.on('click',()=>openCard(c.id));}if(detail)for(const a of M.members(c))L.circleMarker([a.lat,a.lng],{radius:5,color:'white',weight:1,fillColor:'#c5473c',fillOpacity:1}).bindTooltip(e(a.road)+' '+e(a.number)).addTo(map);}
 if(all.length)map.fitBounds(all,{padding:[24,24],maxZoom:detail?18:15});if(report){const bounds=L.latLngBounds(all);if(bounds.isValid())L.rectangle(bounds.pad(.03),{color:'#b74337',weight:2,dashArray:'6 4',fill:false,interactive:false}).addTo(map);}
 setTimeout(()=>{if(maps.includes(map))map.invalidateSize();},30);return map;
}
function openCard(id){if(demoRole==='assistant')return;const c=card(id);if(!c)return;selected=id;const l=M.active(data,id);dialog(`<div class="detailHeader"><div><h2>${t('Kort','Card')} ${e(c.number)} · ${e(c.name)}</h2><p>${e(areaName(c.area_id))}</p></div>${badge(c)}</div><div class="facts"><div><small>${t('Besøg i alt','Total visits')}</small><b>${M.count(c)}</b></div><div><small>${t('Senest gennemgået','Last completed')}</small><b>${fmt(c.last_completed)}</b></div><div><small>${t('Udleveret til','Assigned to')}</small><b>${l?e(person(l.publisher_id)):'—'}</b></div></div>${c.polygon.length?'<div class="map detailMap" id="detailMap"></div>':`<div class="empty">${t('Midlertidigt kort · geografi kan tilføjes i den installerede app.','Temporary card · add geography in the installed app.')}</div>`}<p class="mapCaption">${t('Kun besøg, som ikke er markeret IB, har en rød prik. Alt er opdigtet.','Only visits without a DNC flag have a red dot. Everything is fictional.')}</p><div class="actions noPrint"><button class="primary" data-do="${l?'return':'assign'}" data-id="${e(c.id)}">${l?t('Indlever kort','Return card'):t('Udlever kort','Assign card')}</button>${!l?`<button data-do="move" data-id="${e(c.id)}">${c.in_folder?t('Tilbage i kassen','Back to the storage box'):t('Læg i mappen','Put in the carry folder')}</button>`:''}<button data-do="new-note" data-id="${e(c.id)}">${t('Tilføj note','Add note')}</button><button data-do="print-card">${t('Print demo-visning','Print demo view')}</button></div><details style="margin-top:20px"><summary>${t('Adresser og IB · opdigtede eksempler','Addresses and DNC · fictional examples')}</summary><div class="addressList">${c.addresses.map(a=>`<div class="listLine"><span>${e(a.road)} ${e(a.number)} ${a.dnc?'<span class="badge warn">'+t('IB','DNC')+'</span>':''}</span><button data-do="dnc" data-id="${e(a.id)}">${a.dnc?t('Fjern IB','Remove DNC'):t('Markér IB','Mark DNC')}</button></div>`).join('')||'—'}</div></details><details style="margin-top:15px"><summary>${t('Udleveringshistorik','Assignment history')}</summary><div class="tablewrap tableWrap"><table><thead><tr><th>${t('Forkynder','Publisher')}</th><th>${t('Udleveret','Assigned')}</th><th>${t('Indleveret','Returned')}</th></tr></thead><tbody>${data.loans.filter(x=>x.card_id===id).slice().sort((a,b)=>b.assigned.localeCompare(a.assigned)).map(x=>`<tr><td>${e(person(x.publisher_id))}</td><td>${fmt(x.assigned)}</td><td>${fmt(x.returned)}</td></tr>`).join('')}</tbody></table></div></details>${data.notes.some(n=>n.card_id===id)?`<h3>${t('Noter','Notes')}</h3>${data.notes.filter(n=>n.card_id===id).map(n=>`<p class="detailNotes">${e(n.text)}</p>`).join('')}`:''}<p class="printOnly">DEMO · ${t('Opdigtede data · dette er ikke et rigtigt distriktskort','Fictional data · this is not a real territory card')}</p>`);if(c.polygon.length)mountMap('detailMap',[c],{detail:true});}
function assignForm(id){const c=card(id);if(!c||M.active(data,id))return;dialog(`<h2>${t('Udlever kort','Assign card')} ${e(c.number)}</h2><form data-form="assign" data-id="${e(id)}"><label>${t('Forkynder','Publisher')}<select name="publisher" required>${data.publishers.map(p=>`<option value="${e(p.id)}">${e(p.name)}</option>`).join('')}</select></label><label>${t('Dato','Date')}<input name="date" type="date" max="${data.today}" value="${data.today}" required></label><p>${t('Kortet fjernes fra mappen og står som udleveret.','The card leaves the carry folder and becomes assigned.')}</p><div class="actions"><button class="primary">${t('Bekræft udlevering','Confirm assignment')}</button><button type="button" data-do="close">${t('Annuller','Cancel')}</button></div></form>`);}
