function noteForm(id=''){dialog(`<h2>${t('Tilføj note','Add note')}</h2><form data-form="note"><label>${t('Kort · valgfrit','Card · optional')}<select name="card_id"><option value="">${t('Generel note','General note')}</option>${data.cards.slice().sort(byNumber).map(c=>`<option value="${e(c.id)}" ${id===c.id?'selected':''}>${e(c.number)} · ${e(c.name)}</option>`).join('')}</select></label><label>${t('Note · brug kun opdigtede oplysninger','Note · use fictional information only')}<textarea name="text" maxlength="1000" required></textarea></label><label class="check"><input type="checkbox" name="task" checked>${t('Vis som opgave','Show as task')}</label><div class="actions"><button class="primary">${t('Gem note','Save note')}</button></div></form>`);}
function createForm(){dialog(`<h2>${t('Opret midlertidigt kort','Create temporary card')}</h2><form data-form="create"><label>${t('Kortnummer','Card number')}<input name="number" maxlength="20" required></label><label>${t('Navn','Name')}<input name="name" maxlength="100"></label><label>${t('Område','Area')}<select name="area_id">${data.areas.map(a=>`<option value="${a.id}">${e(a.name)}</option>`).join('')}</select></label><label>${t('Type','Type')}<select name="kind"><option value="By">${t('By','Urban')}</option><option value="Land">${t('Land','Rural')}</option><option value="Ukendt">${t('Ukendt','Unknown')}</option></select></label><p class="hint">${t('Nummerregister først; adresser og print kan tilføjes i den installerede app.','Start with the number register; add addresses and printing in the installed app.')}</p><button class="primary">${t('Opret kort','Create card')}</button></form>`);}
document.addEventListener('click',ev=>{const go=ev.target.closest('[data-go]');if(go){if(demoRole==='assistant'&&!['desk','settings'].includes(go.dataset.go))return;if(el('dialog').open&&!close())return;screen=go.dataset.go;if(go.dataset.preset){filter=go.dataset.preset;area='';search='';}setMenu(false,mobileMenuOpen);render();return;}const b=ev.target.closest('[data-do]');if(b){ev.preventDefault();try{const a=b.dataset.do,id=b.dataset.id;if(demoRole==='assistant'&&!['close','assign','return'].includes(a))return;switch(a){case 'close':close();break;case 'open':case 'map-card':openCard(id);break;case 'assign':assignForm(id);break;case 'return':returnForm(id);break;case 'new-card':createForm();break;case 'new-note':noteForm(id);break;case 'new-publisher':dialog(`<h2>${t('Tilføj demoforkynder','Add demo publisher')}</h2><form data-form="publisher"><label>${t('Opdigtet navn','Fictional name')}<input name="name" maxlength="80" required></label><button class="primary">${t('Tilføj','Add')}</button></form>`);break;case 'move':M.move(data,id,!card(id).in_folder);save();openCard(id);break;case 'dnc':{const c=card(selected),address=c.addresses.find(x=>x.id===id);address.dnc=!address.dnc;address.dnc_date=data.today;save();openCard(c.id);break;}case 'resolve':{const n=data.notes.find(n=>n.id===id);n.resolved=!n.resolved;save();render();break;}case 'report-mode':reportMode=b.dataset.mode;render();document.querySelector('[data-mode="'+reportMode+'"]')?.focus();break;
case 'correct-loan':correctLoanForm(id);break;
case 'delete-loan':deleteLoanForm(id);break;
case 'delete-completion':if(confirm(t('Slet den valgte gennemgang fra demoen?','Delete the selected completion from the demo?'))){M.deleteCompletion(data,id);save();render();}break;
case 'visit':visitForm(id);break;
case 'delete-visit':if(confirm(t('Slet det valgte KTM-besøg fra demoen?','Delete the selected CO visit from the demo?'))){data.visits=data.visits.filter(v=>v.id!==id);save();render();}break;case 'print-report':window.print();break;case 'print-card':document.body.classList.add('printingCard');window.print();break;case 'reset':if(confirm(t('Slet alle demoændringer i denne browser og begynd forfra?','Delete all demo changes in this browser and start again?'))){data=M.seed();resetReport();save();filter='all';search='';area='';selected='';screen='home';render();toast(t('Demoen er nulstillet.','The demo has been reset.'));}break;}}catch(err){const n=el('error');if(n)n.textContent=errorMessage(err);else toast(errorMessage(err));}return;}const row=ev.target.closest('[data-card]');if(row&&!ev.target.closest('button,a,input,select'))openCard(row.dataset.card);});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&mobileMenuOpen&&!el('dialog').open){ev.preventDefault();setMenu(false,true);return;}const row=ev.target.closest('[data-card]');if(row&&ev.target===row&&['Enter',' '].includes(ev.key)){ev.preventDefault();openCard(row.dataset.card);}});
document.addEventListener('input',ev=>{if(ev.target.closest('dialog form'))dirty=true;const {id,value,selectionStart,selectionEnd}=ev.target;
 if(id==='search'||id==='historySearch'){
  if(id==='search')search=value;else historyQuery=value;
  render();el(id).focus();el(id).setSelectionRange(selectionStart,selectionEnd);
 }});
document.addEventListener('change',ev=>{if(ev.target.id==='demoRole'){if(el('dialog').open&&!close())return;demoRole=ev.target.value;screen=demoRole==='assistant'?'desk':'home';render();return;}if(ev.target.id==='language'){if(el('dialog').open&&!close()){el('language').value=lang;return;}lang=ev.target.value;try{localStorage.setItem(LANG,lang);}catch{}render();return;}if(['filter','area','color','reportYear','calendarYear'].includes(ev.target.id)){if(ev.target.id==='filter')filter=ev.target.value;if(ev.target.id==='area')area=ev.target.value;if(ev.target.id==='color')color=ev.target.value;if(ev.target.id==='reportYear')reportYear=Number(ev.target.value);if(ev.target.id==='calendarYear')calendarYear=Number(ev.target.value);render();}});
document.addEventListener('submit',ev=>{const f=ev.target;if(!f.dataset.form)return;ev.preventDefault();if(demoRole==='assistant'&&!['assign','return'].includes(f.dataset.form))return;if(!f.reportValidity())return;const values=Object.fromEntries(new FormData(f));try{switch(f.dataset.form){
case 'preview-correction':previewCorrection(f.dataset.id,values.publisher,values.date);return;
case 'correct-loan':M.correctAssignment(data,f.dataset.id,values.publisher,values.date);break;
case 'delete-loan':M.deleteAssignment(data,f.dataset.id,values.location);break;
case 'visit':{const visit=data.visits.find(v=>v.id===f.dataset.id),fields={date:values.date,note:values.note.trim()};if(visit)Object.assign(visit,fields);else data.visits.push({id:M.id(),...fields});break;}
case 'assign':M.assign(data,f.dataset.id,values.publisher,values.date);break;case 'return':M.finish(data,f.dataset.id,values.date,!!values.completed,values.note,!!values.task);break;case 'create':M.create(data,values.number,values.name,values.area_id,values.kind);break;case 'publisher':{const name=values.name.trim();if(!name)throw Error(t('Skriv et opdigtet navn.','Enter a fictional name.'));data.publishers.push({id:M.id(),name:'Demo · '+name});break;}case 'note':if(!values.text.trim())throw Error(t('Skriv en note.','Enter a note.'));data.notes.push({id:M.id(),card_id:values.card_id||null,text:values.text.trim(),task:!!values.task,resolved:false,date:data.today});break;}const persisted=save();close(true);toast(persisted?t('Demoændringen er gemt i din browser.','The demo change is saved in your browser.'):t('Ændringen findes kun i denne åbne fane.','The change is kept in this tab only.'));}catch(err){el('error').textContent=errorMessage(err);}});
el('dialog').addEventListener('cancel',ev=>{ev.preventDefault();close();});el('menu').addEventListener('click',()=>setMenu(!mobileMenuOpen));
try{render();}catch(err){el('content').innerHTML='<section class="panel"><h1>LTM Demo</h1><p>'+e(t('Demodata kunne ikke læses. Nulstil for at starte forfra.','Demo data could not be read. Reset to start again.'))+'</p><button data-do="reset">'+t('Nulstil demo','Reset demo')+'</button></section>';}

window.addEventListener('afterprint',()=>document.body.classList.remove('printingCard'));
